329	    /// Set a synthetic span for the node and all its descendants, and add hints
330	    /// with the original indices to any syntax errors or warnings.
331	    pub fn synthesize(&mut self, span: Span) {
332	        self.synthesize_with(
333	            0,
334	            &|_, _| span,
335	            // Sub-ranges are removed since the overall range is not accurate.
336	            &|_, sub_range| *sub_range = None,
337	            &|offset, len| {
338	                Some(if len == 0 {
339	                    eco_format!("at index `{offset}`")
340	                } else {
341	                    eco_format!("from index `{offset}` to `{}`", offset + len)
342	                })
343	            },
344	        );
345	    }
346	
347	    /// Set a raw range span for each node.
348	    ///
349	    /// The range is determined by mapping the node's ranges through the given
350	    /// `mapper`.
351	    ///
352	    /// Returns an error with the mapper's length if it was shorter than the
353	    /// length of the source text.
354	    pub fn synthesize_mapped(
355	        &mut self,
356	        id: FileId,
357	        mapper: &RangeMapper,
358	    ) -> Result<(), EcoString> {
359	        if self.len() > mapper.total_len() {
360	            // TODO: Should we error if not exactly equal?
361	            return Err(eco_format!(
362	                "text length ({}) is greater than mapper length ({})",
363	                self.len(),
364	                mapper.total_len(),
365	            ));
366	        }
367	        self.synthesize_with(
368	            0,
369	            &|offset, len| Span::from_range(id, mapper.map(offset..offset + len)),
370	            &|offset, sub_range| {
371	                if let Some(sr) = sub_range {
372	                    *sr = mapper.map_sub_range(offset, *sr);
373	                }
374	            },
375	            &|_, _| None,
376	        );
377	        Ok(())
378	    }
379	
380	    /// Set a custom span for each node given its offset and length, and update
381	    /// any sub-ranges based on their offset.
382	    ///
383	    /// Should be called with `offset = 0` on the root node.
384	    fn synthesize_with(
385	        &mut self,
386	        mut offset: usize,
387	        map_span: &impl Fn(usize, usize) -> Span,
388	        update_sub_range: &impl Fn(usize, &mut Option<SubRange>),
389	        add_hint: &impl Fn(usize, usize) -> Option<EcoString>,
390	    ) {
391	        let len = self.len();
392	        self.span = map_span(offset, len);
393	        let mut data = &mut self.data;
394	        loop {
395	            match data {
396	                Node::Leaf(_, _) => break,
397	                Node::Inner(inner, _) => {
398	                    let inner = Arc::make_mut(inner);
399	                    inner.upper = self.span.number();
400	                    for child in &mut inner.children {
401	                        child.synthesize_with(
402	                            offset,
403	                            map_span,
404	                            update_sub_range,
405	                            add_hint,
406	                        );
407	                        offset += child.len();
408	                    }
409	                    break;
410	                }
411	                Node::Error(err, _) => {
412	                    let err = Arc::make_mut(err);
413	                    for (_hint, sub_range) in err.hints.make_mut() {
414	                        update_sub_range(offset, sub_range);
415	                    }
416	                    if let Some(hint) = add_hint(offset, len) {
417	                        err.hints.push((hint, None));
418	                    }
419	                    break;
420	                }
421	                Node::Warning(warn, _) => {
422	                    let warn = Arc::make_mut(warn);
423	                    update_sub_range(offset, &mut warn.sub_range);
424	                    for (_hint, sub_range) in warn.hints.make_mut() {
425	                        update_sub_range(offset, sub_range);
426	                    }
427	                    if let Some(hint) = add_hint(offset, len) {
428	                        warn.hints.push((hint, None));
429	                    }
430	                    data = &mut warn.child;
431	                }
432	            }
433	        }
434	    }
