436	    /// Whether the two syntax nodes are the same apart from spans.
437	    pub fn spanless_eq(&self, other: &Self) -> bool {
438	        self.kind() == other.kind() && {
439	            let mut data_a = &self.data;
440	            let mut data_b = &other.data;
441	            loop {
442	                match (data_a, data_b) {
443	                    (Node::Leaf(a, _), Node::Leaf(b, _)) => break a == b,
444	                    (Node::Inner(a, _), Node::Inner(b, _)) => {
445	                        break a.spanless_eq(b);
446	                    }
447	                    (Node::Error(a, _), Node::Error(b, _)) => break a == b,
448	                    (Node::Warning(a, _), Node::Warning(b, _))
449	                        if a.message == b.message && a.hints == b.hints =>
450	                    {
451	                        data_a = &a.child;
452	                        data_b = &b.child;
453	                    }
454	                    _ => break false,
455	                }
456	            }
457	        }
458	    }
459	}
