461	impl SyntaxNode {
462	    /// Convert the child to another kind.
463	    ///
464	    /// Panics if trying to convert to or from an error.
465	    #[track_caller]
466	    pub(super) fn convert_to_kind(&mut self, new_kind: SyntaxKind) {
467	        if new_kind.is_error() {
468	            panic!("cannot convert to an error, use `convert_to_error` instead");
469	        } else if self.kind().is_error() {
470	            // `.kind()` checks both errors and warnings that wrap errors.
471	            panic!("cannot convert an error to a different kind");
472	        }
473	        // Must assign through warnings as well, since they duplicate the kind.
474	        let mut data = &mut self.data;
475	        loop {
476	            match data {
477	                Node::Leaf(_, kind) | Node::Inner(_, kind) => {
478	                    *kind = new_kind;
479	                    break;
480	                }
481	                Node::Error(_, _) => unreachable!(),
482	                Node::Warning(warn, kind) => {
483	                    *kind = new_kind;
484	                    data = &mut Arc::make_mut(warn).child;
485	                }
486	            }
487	        }
488	    }
489	
490	    /// Convert the child to an error, if it isn't already one.
491	    pub(super) fn convert_to_error(&mut self, message: impl Into<EcoString>) {
492	        if !self.kind().is_error() {
493	            let text = std::mem::take(self).full_text();
494	            *self = SyntaxNode::error(message.into(), text);
495	        }
496	    }
497	
498	    /// Convert the child to an error stating that the given thing was
499	    /// expected, but the current kind was found.
500	    pub(super) fn expected(&mut self, expected: &str) {
501	        let kind = self.kind();
502	        self.convert_to_error(eco_format!("expected {expected}, found {}", kind.name()));
503	        if kind.is_keyword() && matches!(expected, "identifier" | "pattern") {
504	            self.hint(eco_format!(
505	                "keyword `{text}` is not allowed as an identifier; try `{text}_` instead",
506	                text = self.leaf_text(),
507	            ));
508	        }
509	    }
510	
511	    /// Convert the child to an error stating it was unexpected.
512	    pub(super) fn unexpected(&mut self) {
513	        self.convert_to_error(eco_format!("unexpected {}", self.kind().name()));
514	    }
515	
516	    /// Assign spans to each node.
517	    pub(super) fn numberize(
518	        &mut self,
519	        id: FileId,
520	        within: Range<u64>,
521	    ) -> NumberingResult {
522	        if within.start >= within.end {
523	            Err(Unnumberable)
524	        } else if let Some((inner, span)) = self.inner_and_span_mut() {
525	            inner.numberize(span, id, None, within)
526	        } else {
527	            self.span =
528	                Span::from_number(id, SpanNumber((within.start + within.end) / 2));
529	            Ok(())
530	        }
531	    }
532	
533	    /// Traverse the tree in-order, calling `f` on each node and recursing on
534	    /// the returned nodes. Note that `f` can prune the traversal at any point
535	    /// by yielding `[].iter()` instead of the actual children slice of an inner
536	    /// node.
537	    fn traverse(&self, mut f: impl FnMut(&Self) -> std::slice::Iter<'_, Self>) {
538	        fn recursive_step(
539	            node: &SyntaxNode,
540	            f: &mut impl FnMut(&SyntaxNode) -> std::slice::Iter<'_, SyntaxNode>,
541	        ) {
542	            for child in f(node) {
543	                recursive_step(child, f);
544	            }
545	        }
546	        // We pass in `&mut impl FnMut` so our caller doesn't have to.
547	        recursive_step(self, &mut f);
548	    }
549	
550	    /// Whether this is a leaf node.
551	    pub(super) fn is_leaf(&self) -> bool {
552	        matches!(self.node_ref(), NodeRef::Leaf(_))
553	        // TODO: Should we also treat non-empty errors as leaves?
554	    }
555	
556	    /// Whether this is an inner node.
557	    pub(super) fn is_inner(&self) -> bool {
558	        matches!(self.node_ref(), NodeRef::Inner(_))
559	    }
560	
561	    /// The number of descendants, including the node itself.
562	    pub(super) fn descendants(&self) -> usize {
563	        match self.node_ref() {
564	            NodeRef::Leaf(_) | NodeRef::Error(_) => 1,
565	            NodeRef::Inner(inner) => inner.descendants,
566	        }
567	    }
568	
569	    /// The node's children, mutably.
570	    pub(super) fn children_mut(&mut self) -> &mut [SyntaxNode] {
571	        if let Some((inner, _)) = self.inner_and_span_mut() {
572	            &mut inner.children
573	        } else {
574	            &mut []
575	        }
576	    }
577	
578	    /// Replaces a range of children with a replacement.
579	    ///
580	    /// May have mutated the children if it returns `Err(_)`.
581	    pub(super) fn replace_children(
582	        &mut self,
583	        range: Range<usize>,
584	        replacement: Vec<SyntaxNode>,
585	    ) -> NumberingResult {
586	        if let Some((inner, span)) = self.inner_and_span_mut() {
587	            inner.replace_children(span, range, replacement)
588	        } else {
589	            Ok(())
590	        }
591	    }
592	
593	    /// Update this node after changes were made to one of its children.
594	    pub(super) fn update_parent(
595	        &mut self,
596	        prev_len: usize,
597	        new_len: usize,
598	        prev_descendants: usize,
599	        new_descendants: usize,
600	    ) {
601	        if let Some((inner, _)) = self.inner_and_span_mut() {
602	            inner.update_parent(prev_len, new_len, prev_descendants, new_descendants);
603	        }
604	    }
605	
606	    /// The upper bound of assigned numbers in this subtree.
607	    pub(super) fn upper(&self) -> u64 {
608	        match self.node_ref() {
