1043	/// Map a vector of hints with optional sub-ranges to one with optional
1044	/// diagnostic spans derived from a parent span.
1045	fn build_diagnostic_hints(
1046	    parent_span: Span,
1047	    hints: &EcoVec<(EcoString, Option<SubRange>)>,
1048	) -> EcoVec<Spanned<EcoString, DiagSpan>> {
1049	    hints
1050	        .iter()
1051	        .map(|(message, sub_range)| {
1052	            let msg = message.clone();
1053	            match *sub_range {
1054	                Some(sr) => Spanned::new(msg, DiagSpan::from_span(parent_span, Some(sr))),
1055	                None => Spanned::detached(msg),
1056	            }
1057	        })
1058	        .collect()
1059	}
