1061	/// A syntax node in a context.
1062	///
1063	/// Knows its exact offset in the file and provides access to its
1064	/// children, parent and siblings.
1065	///
1066	/// **Note that all sibling and leaf accessors skip over trivia!**
1067	#[derive(Clone)]
1068	pub struct LinkedNode<'a> {
1069	    /// The underlying syntax node.
1070	    node: &'a SyntaxNode,
1071	    /// The parent of this node.
1072	    parent: Option<Rc<Self>>,
1073	    /// The index of this node in its parent's children array.
1074	    index: usize,
1075	    /// This node's byte offset in the source file.
1076	    offset: usize,
1077	}
1078	
1079	impl<'a> LinkedNode<'a> {
1080	    /// Start a new traversal at a root node.
1081	    pub fn new(root: &'a SyntaxNode) -> Self {
1082	        Self { node: root, parent: None, index: 0, offset: 0 }
1083	    }
1084	
1085	    /// Get the contained syntax node.
1086	    pub fn get(&self) -> &'a SyntaxNode {
1087	        self.node
1088	    }
1089	
1090	    /// The index of this node in its parent's children list.
1091	    pub fn index(&self) -> usize {
1092	        self.index
1093	    }
1094	
1095	    /// The absolute byte offset of this node in the source file.
1096	    pub fn offset(&self) -> usize {
1097	        self.offset
1098	    }
1099	
1100	    /// The byte range of this node in the source file.
1101	    pub fn range(&self) -> Range<usize> {
1102	        self.offset..self.offset + self.node.len()
1103	    }
1104	
1105	    /// An iterator over this node's children.
1106	    pub fn children(&self) -> LinkedChildren<'a> {
1107	        LinkedChildren {
1108	            parent: Rc::new(self.clone()),
1109	            iter: self.node.children().enumerate(),
1110	            front: self.offset,
1111	            back: self.offset + self.len(),
1112	        }
1113	    }
1114	
1115	    /// Find a descendant with the given span.
1116	    pub fn find(&self, span: Span) -> Option<Self> {
1117	        match span.get() {
1118	            SpanKind::Detached => None,
1119	            SpanKind::Number { id: _, num } => self.find_number(num),
1120	            SpanKind::Range { id: _, range } => self.find_range(range.start, range.end),
1121	        }
1122	    }
1123	
1124	    /// Find the descendant whose span number matches the given number.
1125	    ///
1126	    /// This relies on the ordering guarantees of numbered spans:
1127	    /// - The number of a parent is smaller than the numbers of all its children
1128	    /// - The numbers of sibling nodes always increase from left to right
1129	    pub(crate) fn find_number(&self, target: SpanNumber) -> Option<Self> {
1130	        let number = self.span().number();
1131	        if number == target.0 {
1132	            return Some(self.clone());
1133	        }
1134	
1135	        // The parent of a subtree has a smaller span number than all of its
1136	        // descendants. Therefore, we can bail out early if the target span's
1137	        // number is smaller than our number.
1138	        if self.node.is_inner() && number < target.0 {
1139	            // Use `self.children()`, not `inner.children()` to preserve being
1140	            // in a `LinkedNode`.
1141	            let mut children = self.children().peekable();
1142	            while let Some(child) = children.next() {
1143	                // Every node in this child's subtree has a smaller span number than
1144	                // the next sibling. Therefore we only need to recurse if the next
1145	                // sibling's span number is larger than the target span's number.
1146	                if children.peek().is_none_or(|next| next.span().number() > target.0)
1147	                    && let Some(found) = child.find_number(target)
1148	                {
1149	                    return Some(found);
1150	                }
1151	            }
1152	        }
1153	
1154	        None
1155	    }
1156	
1157	    /// Find the descendant whose byte range matches the given range exactly.
1158	    pub(crate) fn find_range(&self, start: usize, end: usize) -> Option<Self> {
1159	        if start == self.offset && end == self.offset + self.len() {
1160	            return Some(self.clone());
1161	        }
1162	        for child in self.children() {
1163	            // Descend into the single child which fully covers the range.
1164	            if child.offset <= start && end <= child.offset + child.len() {
1165	                return child.find_range(start, end);
1166	            }
1167	        }
1168	        None
1169	    }
1170	
1171	    /// Get the [`SyntaxMode`] we will be in when immediately after this node.
1172	    ///
1173	    /// Unlike some other `LinkedNode` methods, this does not treat all trivia
1174	    /// the same: it returns `None` for both comments and the bodies of raw text
1175	    /// and returns `Some` for whitespace (based on the parent's mode). The only
1176	    /// other way this would return `None` is when inside a partial tree, i.e.
1177	    /// one not rooted in `Markup`, `Math`, or `Code`.
1178	    ///
1179	    /// Also note that errors inherit the mode of their parent.
1180	    pub fn mode_after(&self) -> Option<SyntaxMode> {
1181	        match self.kind().mode_after() {
1182	            ModeAfter::Known(mode) => Some(mode),
1183	            // Comments and the bodies of raw text have no mode.
1184	            ModeAfter::None => None,
1185	            ModeAfter::Text if self.parent_kind() == Some(SyntaxKind::Raw) => None,
1186	            ModeAfter::RawDelim if self.index == 0 => None,
1187	            // Text not under raw is always markup.
1188	            ModeAfter::Text => Some(SyntaxMode::Markup),
1189	            // An opening dollar sign starts math mode.
1190	            ModeAfter::Dollar if self.index == 0 => Some(SyntaxMode::Math),
1191	            // Spaces at the left/right of an equation are still in math mode.
1192	            ModeAfter::Space if self.parent_kind() == Some(SyntaxKind::Equation) => {
1193	                Some(SyntaxMode::Math)
1194	            }
1195	            // The position after something embedded with a hash is still code.
1196	            ModeAfter::Embeddable
1197	                if self
1198	                    .prev_sibling_with_trivia()
1199	                    .is_some_and(|prev| prev.kind() == SyntaxKind::Hash) =>
1200	            {
1201	                Some(SyntaxMode::Code)
1202	            }
1203	            // Otherwise, we're simply based on our parent's mode.
1204	            ModeAfter::Parent
1205	            | ModeAfter::RawDelim
1206	            | ModeAfter::Space
1207	            | ModeAfter::Dollar
1208	            | ModeAfter::Embeddable => self.parent_mode(),
1209	        }
