1313	    /// Find the leftmost contained non-trivia leaf.
1314	    pub fn leftmost_leaf(&self) -> Option<Self> {
1315	        if self.is_leaf() && !self.kind().is_trivia() && !self.kind().is_error() {
1316	            return Some(self.clone());
1317	        }
1318	
1319	        for child in self.children() {
1320	            if let Some(leaf) = child.leftmost_leaf() {
1321	                return Some(leaf);
1322	            }
1323	        }
1324	
1325	        None
1326	    }
1327	
1328	    /// Get the leaf immediately before the specified byte offset.
1329	    fn leaf_before(&self, cursor: usize) -> Option<Self> {
1330	        if self.node.children().len() == 0 && cursor <= self.offset + self.len() {
1331	            return Some(self.clone());
1332	        }
1333	
1334	        let mut offset = self.offset;
1335	        let count = self.node.children().len();
1336	        for (i, child) in self.children().enumerate() {
1337	            let len = child.len();
1338	            if (offset < cursor && cursor <= offset + len)
1339	                || (offset == cursor && i + 1 == count)
1340	            {
1341	                return child.leaf_before(cursor);
1342	            }
1343	            offset += len;
1344	        }
1345	
1346	        None
1347	    }
1348	
1349	    /// Get the leaf after the specified byte offset.
1350	    fn leaf_after(&self, cursor: usize) -> Option<Self> {
1351	        if self.node.children().len() == 0 && cursor < self.offset + self.len() {
1352	            return Some(self.clone());
1353	        }
1354	
1355	        let mut offset = self.offset;
1356	        for child in self.children() {
1357	            let len = child.len();
1358	            if offset <= cursor && cursor < offset + len {
1359	                return child.leaf_after(cursor);
1360	            }
1361	            offset += len;
1362	        }
1363	
1364	        None
1365	    }
1366	
1367	    /// Get the leaf at the specified byte offset.
1368	    pub fn leaf_at(&self, cursor: usize, side: Side) -> Option<Self> {
1369	        match side {
1370	            Side::Before => self.leaf_before(cursor),
1371	            Side::After => self.leaf_after(cursor),
1372	        }
1373	    }
1374	
1375	    /// Find the rightmost contained non-trivia leaf.
1376	    pub fn rightmost_leaf(&self) -> Option<Self> {
1377	        if self.is_leaf() && !self.kind().is_trivia() {
1378	            return Some(self.clone());
1379	        }
1380	
1381	        for child in self.children().rev() {
1382	            if let Some(leaf) = child.rightmost_leaf() {
1383	                return Some(leaf);
1384	            }
1385	        }
1386	
1387	        None
1388	    }
1389	
1390	    /// Get the leftmost non-trivia leaf after this node.
1391	    pub fn next_leaf(&self) -> Option<Self> {
1392	        let mut node = self.clone();
1393	        while let Some(next) = node.next_sibling() {
1394	            if let Some(leaf) = next.leftmost_leaf() {
1395	                return Some(leaf);
1396	            }
1397	            node = next;
1398	        }
1399	        self.parent()?.next_leaf()
1400	    }
1401	}
